<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { spotifyApi } from '@/services/spotifyApi'
import { getImageUrl, formatDuration } from '@/utils/helpers'
import { Haptics, ImpactStyle } from '@capacitor/haptics'

const router = useRouter()
const playlists = ref<any[]>([]); const savedAlbums = ref<any[]>([]); const savedTracks = ref<any[]>([]); const isLoading = ref(false); const activeTab = ref<'playlists'|'albums'|'tracks'>('playlists')
async function load() { isLoading.value = true; try { const [p, a, t] = await Promise.allSettled([spotifyApi.getUserPlaylists(50), spotifyApi.getSavedAlbums(50), spotifyApi.getSavedTracks(50)]); if (p.status === 'fulfilled') playlists.value = p.value.items; if (a.status === 'fulfilled') savedAlbums.value = a.value.items.map(i => i.album); if (t.status === 'fulfilled') savedTracks.value = t.value.items.map(i => i.track) } catch { console.error('Failed to load library') } finally { isLoading.value = false } }
function navPlaylist(id: string) { router.push(`/playlist/${id}`) }
function navAlbum(id: string) { router.push(`/album/${id}`) }
function playTrack(t: any, ctx: any[]) { Haptics.impact({ style: ImpactStyle.Light }) }
onMounted(load)
</script>

<template>
  <div class="library-view flex-1 overflow-y-auto pb-[calc(var(--player-height)+16px)]">
    <div class="px-4 pt-[calc(var(--header-height)+16px)] pb-8">
      <div class="flex items-center justify-between mb-6"><h1 class="text-2xl font-bold">Your Library</h1><button class="icon-btn" aria-label="Add"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg></button></div>
      <div class="flex gap-2 overflow-x-auto pb-2 mb-6 -mx-4 px-4" role="tablist"><button @click="activeTab='playlists'" :aria-selected="activeTab==='playlists'" role="tab" class="px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors" :class="activeTab==='playlists'?'bg-green text-black':'bg-gray text-gray hover:bg-gray/50'">Playlists <span class="ml-2 text-xs opacity-75">{{ playlists.length }}</span></button><button @click="activeTab='albums'" :aria-selected="activeTab==='albums'" role="tab" class="px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors" :class="activeTab==='albums'?'bg-green text-black':'bg-gray text-gray hover:bg-gray/50'">Albums <span class="ml-2 text-xs opacity-75">{{ savedAlbums.length }}</span></button><button @click="activeTab='tracks'" :aria-selected="activeTab==='tracks'" role="tab" class="px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors" :class="activeTab==='tracks'?'bg-green text-black':'bg-gray text-gray hover:bg-gray/50'">Liked Songs <span class="ml-2 text-xs opacity-75">{{ savedTracks.length }}</span></button></div>
      <div v-if="isLoading" class="flex justify-center py-12"><div class="loading-spinner"></div></div>
      <div v-else-if="activeTab==='playlists'"><div v-if="playlists.length===0" class="empty-state py-16"><svg class="empty-state-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="2" y="4" width="20" height="16" rx="2"></rect></svg><h3 class="text-lg font-medium mb-2">No playlists yet</h3><p class="text-gray text-sm mb-4">Create a playlist to get started</p><button class="play-btn mx-auto flex items-center justify-center gap-2 text-lg font-semibold"><svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg><span>Create Playlist</span></button></div><div v-else class="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4"><div v-for="p in playlists" :key="p.id" @click="navPlaylist(p.id)" class="card cursor-pointer group"><div class="relative aspect-square mb-3 overflow-hidden rounded"><img v-if="p.images?.length" :src="getImageUrl(p.images)" alt="" class="w-full h-full object-cover transition-transform duration-300 group-hover:scale-105"><div v-else class="w-full h-full bg-gray flex items-center justify-center"><svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="2" y="4" width="20" height="16" rx="2"></rect></svg></div><div class="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center"><button class="play-btn opacity-0 group-hover:opacity-100 transform group-hover:scale-100 scale-90 transition-all"><svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor" style="margin-left: 2px;"><path d="M8 5v14l11-7z"/></svg></button></div></div><p class="font-medium truncate">{{ p.name }}</p><p class="text-xs text-gray truncate">{{ p.tracks?.total }} songs</p></div></div></div>
      <div v-else-if="activeTab==='albums'"><div v-if="savedAlbums.length===0" class="empty-state py-16"><svg class="empty-state-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="4" y="2" width="16" height="20" rx="2"></rect></svg><h3 class="text-lg font-medium mb-2">No saved albums</h3><p class="text-gray text-sm">Save albums to see them here</p></div><div v-else class="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4"><div v-for="a in savedAlbums" :key="a.id" @click="navAlbum(a.id)" class="card cursor-pointer group"><div class="relative aspect-square mb-3 overflow-hidden rounded"><img v-if="a.images?.length" :src="getImageUrl(a.images)" alt="" class="w-full h-full object-cover transition-transform duration-300 group-hover:scale-105"><div class="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center"><button class="play-btn opacity-0 group-hover:opacity-100 transform group-hover:scale-100 scale-90 transition-all"><svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor" style="margin-left: 2px;"><path d="M8 5v14l11-7z"/></svg></button></div></div><p class="font-medium truncate">{{ a.name }}</p><p class="text-xs text-gray truncate">{{ a.artists?.map((x:any)=>x.name).join(', ') }}</p></div></div></div>
      <div v-else-if="activeTab==='tracks'"><div v-if="savedTracks.length===0" class="empty-state py-16"><svg class="empty-state-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/></svg><h3 class="text-lg font-medium mb-2">No liked songs</h3><p class="text-gray text-sm">Tap the heart icon on any track to save it</p></div><div v-else class="space-y-2"><div v-for="(t,i) in savedTracks" :key="t.id" @click="playTrack(t, savedTracks)" class="row-item cursor-pointer group"><div class="flex items-center gap-3 w-16 flex-shrink-0"><span class="text-gray text-sm font-medium w-6 text-right">{{ i+1 }}</span><img v-if="t.album?.images?.length" :src="getImageUrl(t.album.images, 64)" alt="" class="w-10 h-10 rounded object-cover"></div><div class="flex-1 min-w-0"><p class="font-medium truncate">{{ t.name }}</p><p class="text-xs text-gray truncate">{{ t.artists?.map((a:any)=>a.name).join(', ') }}</p></div><div class="flex items-center gap-3 text-gray opacity-0 group-hover:opacity-100 transition-opacity"><span class="text-sm">{{ formatDuration(t.duration_ms) }}</span><button class="icon-btn p-1 text-xs"><svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor" style="margin-left: 2px;"><path d="M8 5v14l11-7z"/></svg></button></div></div></div></div>
    </div>
  </div>
</template>